import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Texture,
    Color
  } = ctx.THREE;

  const root = new Group();
  const card = new Group();
  const resources = [];
  const timelines = [];
  const primitiveResults = [];
  let loadedTexture = null;
  let disposed = false;

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(colors.surface),
    mix(vec3(colors.ink), vec3(colors.paper), uv().y),
    uv().y
  );
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new PlaneGeometry(3.8, 2.45);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.48
  });
  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.position.set(0, -0.08, -0.18);
  contactShadow.scale.set(1.04, 0.9, 1);
  root.add(contactShadow);
  resources.push(shadowGeometry, shadowMaterial);

  const cardGeometry = new PlaneGeometry(3.45, 2.12);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: colors.paper
  });
  const cardSurface = new Mesh(cardGeometry, cardMaterial);
  cardSurface.position.set(0, 0, 0);
  card.add(cardSurface);
  resources.push(cardGeometry, cardMaterial);

  const edgeDepth = 0.035;
  const edgeGeometry = new BoxGeometry(3.55, edgeDepth, 0.045);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  const topEdge = new Mesh(edgeGeometry, edgeMaterial);
  topEdge.position.set(0, 1.07, 0.055);
  card.add(topEdge);

  const bottomEdge = new Mesh(edgeGeometry, edgeMaterial);
  bottomEdge.position.set(0, -1.07, 0.055);
  bottomEdge.scale.x = 0.28;
  card.add(bottomEdge);

  const sideGeometry = new BoxGeometry(edgeDepth, 2.12, 0.045);
  const sideMaterial = new MeshBasicNodeMaterial({
    color: colors.ink
  });
  const leftEdge = new Mesh(sideGeometry, sideMaterial);
  leftEdge.position.set(-1.755, 0, 0.04);
  card.add(leftEdge);

  const rightEdge = new Mesh(sideGeometry, sideMaterial);
  rightEdge.position.set(1.755, 0, 0.04);
  card.add(rightEdge);

  resources.push(edgeGeometry, edgeMaterial, sideGeometry, sideMaterial);
  root.add(card);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const text = String(item?.text ?? '');
    if (!text) continue;

    const role = String(item?.role ?? '').toLowerCase();
    const fontSize = item?.typography?.fontSize ?? (role.includes('caption') ? 18 : 42);
    const textObject = ctx.fontAtlas.createText(text, {
      fontSize,
      color: role.includes('caption') ? colors.accent : colors.ink,
      align: role.includes('attribution') || role.includes('caption') ? 'right' : 'left',
      maxWidthPx: 700,
      letterSpacingPx: role.includes('caption') ? 1.5 : 0
    });

    textObject.position.set(
      role.includes('attribution') || role.includes('caption') ? 1.25 : -1.25,
      role.includes('attribution') || role.includes('caption') ? -0.68 : 0.16,
      0.08
    );
    textObject.scale.setScalar(0.01);
    card.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      loadedTexture = texture;
      if ('colorSpace' in texture && ctx.THREE.SRGBColorSpace) {
        texture.colorSpace = ctx.THREE.SRGBColorSpace;
      }
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    card.position,
    { y: -0.15 },
    { y: 0, duration: 0.7, ease: 'power3.out' }
  );
  timelines.push(entrance);

  const primitiveList = config.cinematicPrimitives ?? [];
  for (const primitive of primitiveList) {
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  let hoverTimeline = null;
  let pressTimeline = null;
  let focused = false;

  const handlers = {
    hover: (active = true) => {
      hoverTimeline?.kill();
      hoverTimeline = gsap.timeline();
      hoverTimeline.to(card.position, {
        y: active ? 0.15 : 0,
        duration: 0.3,
        ease: 'power2.out'
      });
      hoverTimeline.to(card.rotation, {
        z: active ? -0.018 : 0,
        duration: 0.3,
        ease: 'power2.out'
      }, 0);
      if (!active && focused) {
        topEdge.scale.x = 1;
      }
    },

    click: () => {
      pressTimeline?.kill();
      pressTimeline = gsap.timeline();
      pressTimeline.to(card.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      });
      pressTimeline.to(card.scale, {
        x: 1,
        y: 1,
        duration: 0.3,
        ease: 'back.out(3)'
      });
      ctx.emit('hub-journal.select', {
        node: config.id ?? config.nodeId ?? 'hub-journal-quote'
      });
    },

    focus: () => {
      focused = true;
      gsap.to(topEdge.scale, {
        x: 1.04,
        duration: 0.25,
        ease: 'power2.out'
      });
    },

    blur: () => {
      focused = false;
      gsap.to(topEdge.scale, {
        x: 1,
        duration: 0.25,
        ease: 'power2.out'
      });
    }
  };

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    timelines.forEach((timeline) => timeline.kill());
    hoverTimeline?.kill();
    pressTimeline?.kill();

    primitiveResults.forEach((result) => result?.cleanup?.());

    if (loadedTexture?.dispose) loadedTexture.dispose();

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        materials.forEach((material) => material.dispose?.());
      }
    });
  };

  return root;
}
